function Login({onLogin,onBack}:{onLogin:(u:User,t:string)=>void;onBack:()=>void}){
  const [mobile,setMobile]=useState(''),[code,setCode]=useState(''),[step,setStep]=useState<1|2>(1),[busy,setBusy]=useState(false),[debug,setDebug]=useState('')
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);try{if(step===1){const r=await request<{debugCode?:string;message:string}>('/api/auth/request-otp',{method:'POST',body:JSON.stringify({mobile})});setDebug(r.debugCode||'');setStep(2);toast.success(r.message)}else{const r=await request<{token:string;user:User}>('/api/auth/verify-otp',{method:'POST',body:JSON.stringify({mobile,code})});onLogin(r.user,r.token)}}catch(e){toast.error((e as Error).message)}finally{setBusy(false)}}
  return <div className="login-page"><button className="login-back" onClick={onBack}><ArrowLeft/>بازگشت به صفحه اصلی</button><div className="login-orb orb-a"/><div className="login-orb orb-b"/><section className="login-story">
    <button className="logo-button" onClick={onBack}><Logo/></button><div className="hero-copy"><span className="eyebrow"><Zap/>یک API، تمام مدل‌ها</span><h1>مرکز فرمان<br/><em>هوش مصنوعی</em> شما</h1><p>مدل‌های برتر دنیا، مدیریت هزینه و گزارش‌های دقیق؛ همه در یک مسیر امن و یکپارچه.</p></div>
    <div className="trust-row"><div><ShieldCheck/><span><b>امن و کنترل‌شده</b><small>سیاست دسترسی هر کلید</small></span></div><div><Activity/><span><b>محاسبه لحظه‌ای</b><small>توکن و هزینه دقیق</small></span></div></div>
    <div className="model-cloud"><span>OpenAI</span><span>Gemini</span><span>Claude</span><span>DeepSeek</span><span>Kimi</span><span>GLM</span></div>
  </section><section className="login-panel"><form className="login-card" onSubmit={submit}>
    <div className="login-icon"><MessageSquareText/></div><h2>{step===1?'ورود به حساب کاربری':'تأیید شماره موبایل'}</h2><p>{step===1?'شماره موبایل خود را وارد کنید تا کد یک‌بارمصرف برایتان ارسال شود.':<>کد ۶ رقمی ارسال‌شده به <b dir="ltr">{mobile}</b> را وارد کنید.</>}</p>
    {step===1?<label className="field"><span>شماره موبایل</span><div className="input-wrap"><span className="flag">🇮🇷</span><input dir="ltr" value={mobile} onChange={e=>setMobile(e.target.value)} placeholder="09xxxxxxxxx" autoFocus/></div></label>:<label className="field"><span>کد تأیید</span><input className="otp-input" dir="ltr" value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="— — — — — —" autoFocus/>{debug&&<small className="debug-code">کد محیط توسعه: <button type="button" onClick={()=>setCode(debug)}>{debug}</button></small>}</label>}
    <button className="primary-btn full" disabled={busy}>{busy?<RefreshCw className="spin"/>:step===1?'دریافت کد ورود':'ورود به AiBus'}{!busy&&<ArrowLeft/>}</button>
    {step===2&&<button type="button" className="link-btn" onClick={()=>setStep(1)}>ویرایش شماره موبایل</button>}<div className="secure-note"><LockKeyhole/>ورود شما با رمزنگاری امن محافظت می‌شود.</div>
  </form></section></div>
}

function Sidebar({page,setPage,admin,open,close}:{page:Page;setPage:(p:Page)=>void;admin:boolean;open:boolean;close:()=>void}){
  const userItems:{id:Page;label:string;icon:IconType}[]=[{id:'dashboard',label:'نمای کلی',icon:LayoutDashboard},{id:'models',label:'مدل‌ها و آزمایشگاه',icon:Bot},{id:'keys',label:'کلیدهای API',icon:KeyRound},{id:'wallet',label:'کیف پول و شارژ',icon:Wallet},{id:'usage',label:'گزارش مصرف',icon:BarChart3},{id:'tickets',label:'پشتیبانی و تیکت‌ها',icon:LifeBuoy}]
  const adminItems:{id:Page;label:string;icon:IconType}[]=[{id:'admin-dashboard',label:'مرکز کنترل',icon:Gauge},{id:'providers',label:'ارائه‌دهندگان و کلیدها',icon:Network},{id:'admin-models',label:'کاتالوگ و قیمت‌ها',icon:Database},{id:'users',label:'کاربران',icon:Users},{id:'admin-tickets',label:'مرکز پشتیبانی',icon:Headphones},{id:'visits',label:'بازدید و تحلیل سایت',icon:Globe2},{id:'settings',label:'تنظیمات سامانه',icon:Settings}]
  return <><aside className={`sidebar ${open?'open':''}`}><button className="side-close" onClick={close}><X/></button><Logo/><nav><small>فضای کاربری</small>{userItems.map(i=><SideItem key={i.id} {...i} active={page===i.id} click={()=>setPage(i.id)}/>)}{admin&&<><small className="admin-label">مدیریت سامانه</small>{adminItems.map(i=><SideItem key={i.id} {...i} active={page===i.id} click={()=>setPage(i.id)}/>)}</>}</nav><div className="side-status"><div className="pulse-dot"/><div><b>همه سامانه‌ها فعال‌اند</b><small>آخرین بررسی: همین حالا</small></div></div><div className="side-version">AiBus Platform <span>v1.0</span></div></aside>{open&&<div className="overlay" onClick={close}/>}</>
}
function SideItem({label,icon:Icon,active,click}:{label:string;icon:IconType;active:boolean;click:()=>void}){return <button className={`nav-item ${active?'active':''}`} onClick={click}><Icon/><span>{label}</span>{active&&<i/>}</button>}

function PageHead({eyebrow,title,description,children}:{eyebrow?:string;title:string;description:string;children?:ReactNode}){return <div className="page-head"><div>{eyebrow&&<span className="eyebrow-text">{eyebrow}</span>}<h1>{title}</h1><p>{description}</p></div>{children&&<div className="head-actions">{children}</div>}</div>}
function Metric({label,value,sub,icon:Icon,tone='mint',trend}:{label:string;value:string;sub:string;icon:IconType;tone?:string;trend?:string}){return <div className="metric-card"><div className={`metric-icon ${tone}`}><Icon/></div><div className="metric-body"><span>{label}</span><strong dir="ltr">{value}</strong><small>{trend&&<b className="up"><TrendingUp/>{trend}</b>}{sub}</small></div><MoreHorizontal className="metric-more"/></div>}
function Card({title,subtitle,children,action,className=''}:{title?:string;subtitle?:string;children:ReactNode;action?:ReactNode;className?:string}){return <section className={`card ${className}`}>{title&&<header className="card-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>}{children}</section>}
function ChartTip({active,payload,label}:{active?:boolean;payload?:Array<{name:string;value:number;color:string}>;label?:string}){if(!active||!payload?.length)return null;return <div className="chart-tip"><b>{label}</b>{payload.map((p,i)=><span key={i}><i style={{background:p.color}}/>{p.name}: <strong>{p.name.includes('$')?usd(p.value,6):number(p.value)}</strong></span>)}</div>}
function Loading(){return <div className="section-loading"><RefreshCw className="spin"/>در حال دریافت داده‌ها...</div>}
function Empty({text='داده‌ای برای نمایش وجود ندارد.'}:{text?:string}){return <div className="empty"><Database/><p>{text}</p></div>}

function UserDashboard({user}:{user:User}){
  const [data,setData]=useState<any>(null)
  useEffect(()=>{request('/api/dashboard').then(setData).catch(e=>toast.error(e.message))},[])
  if(!data)return <Loading/>
  const t=data.totals
  return <><PageHead eyebrow="فضای کاربری" title={`سلام ${user.displayName} 👋`} description="تصویر زنده‌ای از مصرف، هزینه و عملکرد APIهای شما."><button className="ghost-btn"><Clock3/>۳۰ روز گذشته<ChevronDown/></button><button className="primary-btn"><Plus/>ساخت کلید جدید</button></PageHead>
  <div className="metrics"><Metric label="موجودی دلاری" value={`$${usd(data.walletUsd)}`} sub={`${money(data.walletIrr,0)} ریال`} icon={Wallet}/><Metric label="هزینه دوره" value={`$${usd(t.costUsd)}`} sub="بر اساس مصرف واقعی" icon={CircleDollarSign} tone="violet"/><Metric label="کل توکن" value={number(t.inputTokens+t.outputTokens)} sub={`${number(t.inputTokens)} ورودی · ${number(t.outputTokens)} خروجی`} icon={Sparkles} tone="blue" trend="۱۲٪ "/><Metric label="درخواست موفق" value={number(t.requests)} sub={`میانگین پاسخ ${number(t.avgLatencyMs)}ms`} icon={Activity} tone="orange"/></div>
  <div className="grid-main"><Card title="روند مصرف و هزینه" subtitle="نمای روزانه مصرف توکن و هزینه دلاری" action={<div className="legend"><span><i className="mint"/>توکن</span><span><i className="violet"/>هزینه</span></div>}><div className="chart-lg"><ResponsiveContainer><AreaChart data={data.timeline} margin={{top:16,right:12,bottom:8,left:10}}><defs><linearGradient id="tokens" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#66e3c4" stopOpacity={.4}/><stop offset="95%" stopColor="#66e3c4" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5" vertical={false}/><XAxis dataKey="date" tickFormatter={shortDate} tickMargin={10} axisLine={false} tickLine={false} minTickGap={28}/><YAxis tickFormatter={chartNumber} width={58} tickMargin={10} axisLine={false} tickLine={false} allowDecimals={false}/><Tooltip content={<ChartTip/>}/><Area name="توکن" type="monotone" dataKey="tokens" stroke="#66e3c4" fill="url(#tokens)" strokeWidth={3}/><Line name="هزینه ($)" type="monotone" dataKey="costUsd" stroke="#8b7cff" strokeWidth={2}/></AreaChart></ResponsiveContainer></div></Card>
  <Card title="سهم مدل‌ها" subtitle="براساس تعداد توکن"><div className="donut"><ResponsiveContainer><PieChart><Pie data={data.byModel} dataKey="tokens" nameKey="model" innerRadius={65} outerRadius={94} paddingAngle={3}>{data.byModel.map((_:any,i:number)=><Cell key={i} fill={COLORS[i%COLORS.length]}/>)}</Pie><Tooltip content={<ChartTip/>}/></PieChart></ResponsiveContainer><div className="donut-center"><b>{data.byModel.length}</b><span>مدل فعال</span></div></div><div className="model-legend">{data.byModel.slice(0,5).map((m:any,i:number)=><div key={m.model}><i style={{background:COLORS[i%COLORS.length]}}/><span>{m.model}</span><b>{number(m.tokens)}</b></div>)}</div></Card></div>
  <Card title="مدل‌های پرمصرف" subtitle="رتبه‌بندی بر اساس مصرف ۳۰ روز اخیر"><div className="rank-list">{data.byModel.slice(0,5).map((m:any,i:number)=><div key={m.model}><span className="rank">{i+1}</span><div className="mini-model"><Bot/><span><b>{m.model}</b><small>{number(m.requests)} درخواست</small></span></div><div className="rank-bar"><i style={{width:`${Math.max(8,m.tokens/(data.byModel[0]?.tokens||1)*100)}%`}}/></div><strong>{number(m.tokens)} توکن</strong><em>${usd(m.costUsd,3)}</em></div>)}</div></Card></>
}
const shortDate=(v:string)=>new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'short',day:'numeric'}).format(new Date(v))

function Modal({title,subtitle,close,children,wide=false}:{title:string;subtitle?:string;close:()=>void;children:ReactNode;wide?:boolean}){return <div className="modal-layer" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className={`modal ${wide?'wide':''}`}><header><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" onClick={close}><X/></button></header><div className="modal-body">{children}</div></div></div>}
function Badge({children,tone='default'}:{children:ReactNode;tone?:string}){return <span className={`badge ${tone}`}>{children}</span>}
function Toggle({on,change}:{on:boolean;change:(v:boolean)=>void}){return <button type="button" className={`toggle ${on?'on':''}`} onClick={()=>change(!on)}><i/></button>}
const builtInProviderLogos:Record<string,string>={openai:'/providers/openai.svg',cohere:'/providers/cohere.svg'}
function ProviderLogo({name,url,className='',style}:{name:string;url:string;className?:string;style?:React.CSSProperties}){const logoSource=builtInProviderLogos[name.trim().toLowerCase()]||url;const [failedSource,setFailedSource]=useState('');const initials=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();return <div className={`provider-logo ${className}`} style={style}><span aria-hidden="true">{initials}</span>{logoSource&&failedSource!==logoSource&&<img src={logoSource} alt={`لوگوی ${name}`} onError={()=>setFailedSource(logoSource)}/>}</div>}

