const PRICE_UNIT_LABELS:Record<string,string>={million_text_tokens:'هر ۱ میلیون توکن متن',million_audio_tokens:'هر ۱ میلیون توکن صوت',million_image_tokens:'هر ۱ میلیون توکن تصویر',million_characters:'هر ۱ میلیون کاراکتر',thousand_characters:'هر ۱۰۰۰ کاراکتر',ten_thousand_characters:'هر ۱۰٬۰۰۰ کاراکتر',thousand_calls:'هر ۱۰۰۰ فراخوانی',minute:'هر دقیقه',hour:'هر ساعت',second:'هر ثانیه',message:'هر پیام',voice:'هر صدا',free:'رایگان',contact_sales:'قیمت قراردادی'}
const serviceLabel=(type:string)=>SERVICE_META[type]?.label||type
const priceText=(value:number|null)=>value==null?'تماس با فروش':`$${usd(value,value<.01?6:4)}`

